import type { Metadata } from "next";
import { OG_LOCALES, LOCALES, type Locale } from "./i18n/config";
import { absoluteUrl, hreflangMap, localizedPath } from "./routes";
import { SITE_NAME, SITE_URL } from "./site";

/** Static OG/Twitter images generated by app/opengraph-image.tsx and app/twitter-image.tsx. */
const OG_IMAGE = { url: `${SITE_URL}/opengraph-image`, width: 1200, height: 630, alt: `${SITE_NAME} – CSS clamp() calculator` };

export interface PageMetaInput {
  locale: Locale;
  /** Unlocalized path, e.g. `/about/`. */
  path: string;
  title: string;
  description: string;
}

export function buildMetadata({ locale, path, title, description }: PageMetaInput): Metadata {
  const url = absoluteUrl(localizedPath(locale, path));
  return {
    metadataBase: new URL(SITE_URL),
    title: { absolute: title },
    description,
    applicationName: SITE_NAME,
    alternates: { canonical: url, languages: hreflangMap(path) },
    openGraph: {
      type: "website",
      siteName: SITE_NAME,
      url,
      title,
      description,
      locale: OG_LOCALES[locale],
      alternateLocale: LOCALES.filter((l) => l !== locale).map((l) => OG_LOCALES[l]),
      images: [OG_IMAGE],
    },
    twitter: { card: "summary_large_image", title, description, images: [`${SITE_URL}/twitter-image`] },
  };
}

type Json = Record<string, unknown>;

export function webApplicationLd(locale: Locale, path: string, name: string, description: string): Json {
  return {
    "@context": "https://schema.org",
    "@type": "WebApplication",
    name,
    description,
    url: absoluteUrl(localizedPath(locale, path)),
    inLanguage: locale,
    applicationCategory: "DeveloperApplication",
    operatingSystem: "Any",
    browserRequirements: "Requires JavaScript",
    isAccessibleForFree: true,
    offers: { "@type": "Offer", price: "0", priceCurrency: "USD" },
  };
}

export function faqPageLd(locale: Locale, faq: { q: string; a: string }[]): Json {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    inLanguage: locale,
    mainEntity: faq.map((f) => ({
      "@type": "Question",
      name: f.q,
      acceptedAnswer: { "@type": "Answer", text: f.a },
    })),
  };
}

export function breadcrumbLd(crumbs: { name: string; path: string; locale: Locale }[]): Json {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: crumbs.map((c, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: c.name,
      item: absoluteUrl(localizedPath(c.locale, c.path)),
    })),
  };
}
